import { useEffect, useId, useState, type FormEvent, type ReactNode } from "react";
import { apiFetch, loadResume, saveResume, sessionKey } from "./account-api";
import type { AmlAction, AmlAlert, AmlCase, AmlEntity, AmlEvent, AmlTransaction, AmlView, MonitoringRule, StrDraft, TrainingRole } from "../../packages/aml/types";
import "./aml-workflow.css";
import { RuleComparison } from "./RuleComparison";
import { Challenge } from "./Challenge";

const SESSION_KEY = "twinaml-hk-workflow-session";
const numeric = new Intl.NumberFormat("en-HK", { maximumFractionDigits: 2, minimumFractionDigits: 2 });
type Screen = "alerts" | "challenge" | "entities" | "cases" | "review" | "monitoring" | "comparison";
type Act = (action: AmlAction, message: string) => Promise<AmlView | null>;
const words = (value: string) => value.replaceAll("_", " ");
const money = (value: number, currency = "HKD") => `${currency} ${numeric.format(value)}`;
function time(value: string) { return new Date(value).toLocaleString("en-GB", { timeZone: "Asia/Hong_Kong", day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit", hour12: false }); }
function localInput(value: string) { return new Date(new Date(value).getTime() + 8 * 3_600_000).toISOString().slice(0, 16); }
function savedId(key: string) { return loadResume(key); }
function entityName(view: AmlView, id: string) { return view.entities.find((entity) => entity.id === id)?.name || id; }
function accountEntity(view: AmlView, id: string) { return view.accounts.find((account) => account.id === id)?.entityId || ""; }
function download(value: string, filename: string, type = "application/json") {
  const url = URL.createObjectURL(new Blob([value], { type }));
  const link = document.createElement("a"); link.href = url; link.download = filename; link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
class ApiError extends Error { constructor(message: string, public status: number, public code = "") { super(message); } }
async function api(path: string, body?: object): Promise<AmlView> {
  const response = await apiFetch(path, body === undefined ? undefined : { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
  const result = await response.json().catch(() => null);
  if (!response.ok) throw new ApiError(typeof result?.error === "string" ? words(result.error) : result?.error?.message || "The training service could not complete this action.", response.status, typeof result?.error === "string" ? result.error : "");
  if (!result || !Array.isArray(result.alerts) || !Array.isArray(result.cases)) throw new Error("The training service returned an unreadable response.");
  return result as AmlView;
}

export function AmlWorkflow({ accountId = null }: { accountId?: string | null }) {
  const storageKey = sessionKey(SESSION_KEY, accountId);
  const [view, setView] = useState<AmlView | null>(null);
  const [loading, setLoading] = useState(Boolean(savedId(storageKey)));
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [screen, setScreen] = useState<Screen>("alerts");
  const [alertId, setAlertId] = useState("");
  const [entityId, setEntityId] = useState("");
  const [caseId, setCaseId] = useState("");
  const [query, setQuery] = useState("");
  useEffect(() => {
    document.title = "Hong Kong AML Training · TwinAML";
    const id = savedId(storageKey); if (!id) return;
    let cancelled = false;
    api(`/api/aml-sessions/${encodeURIComponent(id)}`).then((next) => { if (!cancelled) setView(next); })
      .catch((err) => { if (!cancelled) setError(err instanceof Error ? err.message : "Unable to resume the training run."); })
      .finally(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, []);
  async function start() {
    if (busy) return;
    setBusy(true); setError(""); setNotice("");
    try {
      const next = await api("/api/aml-sessions", {});
      setView(next); setScreen("alerts"); setAlertId(""); setEntityId(""); setCaseId(""); setQuery("");
      try { saveResume(storageKey, next.id); setNotice("New training run created. Earlier runs remain saved on the server."); }
      catch { setNotice(accountId ? "Run created and saved to your account. Use My progress to resume it." : `Run created. Browser resume storage is unavailable. Save this run ID: ${next.id}`); }
    } catch (err) { setError(err instanceof Error ? err.message : "Unable to start the training run."); }
    finally { setBusy(false); }
  }
  async function refresh() {
    const id = view?.id || savedId(storageKey); if (!id || busy) return;
    setBusy(true); setError("");
    try { setView(await api(`/api/aml-sessions/${encodeURIComponent(id)}`)); setNotice("Records refreshed. Unsaved form drafts remain on this screen."); }
    catch (err) { setError(err instanceof Error ? err.message : "Unable to refresh records."); }
    finally { setBusy(false); }
  }
  const act: Act = async (action, message) => {
    if (!view || busy) return null;
    setBusy(true); setError(""); setNotice("");
    try {
      const next = await api(`/api/aml-sessions/${encodeURIComponent(view.id)}/actions`, { ...action, revision: view.revision });
      setView(next); setNotice(message); return next;
    } catch (err) {
      if (err instanceof ApiError && err.status === 409 && err.code === "stale_revision") {
        try { setView(await api(`/api/aml-sessions/${encodeURIComponent(view.id)}`)); setError("Another window changed this run. Records have been refreshed. Review your draft and submit again; the action was not repeated."); }
        catch { setError("Another window changed this run. Refresh records before submitting again."); }
      } else setError(err instanceof Error ? err.message : "The action could not be saved.");
      return null;
    } finally { setBusy(false); }
  };
  function openEntity(id: string) { setEntityId(id); setQuery(""); setScreen("entities"); }
  function openCase(id: string) { setCaseId(id); setScreen("cases"); }
  function openAlert(id: string) { setAlertId(id); setScreen("alerts"); }
  const pending = view?.cases.filter((record) => record.status === "pending_review").length || 0;
  const tabs: [Screen, string, number | undefined][] = [["alerts", "Alerts", view?.alerts.filter((alert) => alert.status !== "closed").length], ["challenge", "Challenge", undefined], ["entities", "Entities", undefined], ["cases", "Cases", view?.cases.length], ["review", "Review", pending], ["monitoring", "Monitoring", undefined], ["comparison", "Compare rules", undefined]];
  const selectedAlert = view?.alerts.find((alert) => alert.id === alertId);
  const selectedCase = view?.cases.find((record) => record.id === caseId);
  return <div className="aml">
    <a className="aml-skip" href="#aml-content">Skip to workspace</a>
    <header className="aml-header">
      <a className="aml-brand" href="/">TwinAML<span>Hong Kong AML Training</span></a>
      <form className="aml-global-search" onSubmit={(event) => { event.preventDefault(); setScreen("entities"); }}>
        <label className="aml-sr" htmlFor="aml-global-search">Search entities, accounts or transactions</label>
        <input id="aml-global-search" type="search" value={query} disabled={!view} onChange={(event) => setQuery(event.target.value)} placeholder="Search entity, account or transaction" />
        <button disabled={!view} aria-label="Search records">Search</button>
      </form>
      <div className="aml-header-tools">
        {view && <label className="aml-role">Training role<select value={view.role} disabled={busy} onChange={(event) => act({ type: "switch_role", role: event.target.value as TrainingRole }, "Training role changed. This switch simulates permissions; it is not authentication.")}><option value="analyst">Analyst</option><option value="reviewer">Reviewer</option><option value="administrator">Administrator</option></select></label>}
        <button disabled={busy || loading} onClick={start}>{view ? "New training run" : "Start training run"}</button>
      </div>
    </header>
    <nav className="aml-nav" aria-label="Operational workspace">{tabs.map(([id, label, count]) => <button key={id} onClick={() => { setScreen(id); if (id === "alerts") setAlertId(""); if (id === "cases") setCaseId(""); }} className={screen === id ? "is-active" : ""} aria-current={screen === id ? "page" : undefined}>{label}{count !== undefined && <span>{count}</span>}</button>)}<div className="aml-nav-meta">Synthetic data · HKT (UTC+8)</div></nav>
    {error && <div className="aml-message aml-error" role="alert"><span>{error}</span><button onClick={() => setError("")} aria-label="Dismiss error">×</button></div>}
    {notice && <div className="aml-message aml-notice" role="status"><span>{notice}</span><button onClick={() => setNotice("")} aria-label="Dismiss notification">×</button></div>}
    <main id="aml-content" className="aml-main" aria-busy={busy || loading}>
      {loading ? <section className="aml-card"><h1>Resuming training run…</h1><p>The server is restoring your records and action history.</p></section> : !view ? <section className="aml-start aml-card"><p className="aml-kicker">Operational training workspace</p><h1>Investigate activity. Build a case. Submit it for review.</h1><p>Work with synthetic Hong Kong customer profiles, FPS and cross-border payments, monitoring alerts and source records. The initial monitoring run is ready when you begin.</p><button className="aml-primary" onClick={start} disabled={busy}>{busy ? "Starting…" : "Start training run"}</button><p className="aml-help">Switch between analyst, reviewer and administrator to practise each role. All reports are training drafts. No live account controls or STR submission.</p></section> : <>
        <div className="aml-run-bar"><span>Run <code>{view.id}</code><span className="aml-separator">·</span>Data cutoff <strong>{time(view.asOf)} HKT</strong><span className="aml-separator">·</span>{view.actor}</span><div className="aml-inline"><button className="aml-link" disabled={busy} onClick={refresh}>Refresh</button><button className="aml-link" onClick={() => download(JSON.stringify({ label: "TWINAML SYNTHETIC TRAINING RUN — NO LIVE STR SUBMISSION", ...view }, null, 2), `twinaml-${view.id}.json`)}>Export run</button></div></div>
        {screen === "alerts" && !selectedAlert && <aside className="aml-challenge-entry"><div><strong>Can you finish the shift?</strong><p>Five files, twelve simulated minutes and two investigation slots. Your decisions can pass or fail the mission.</p></div><button className="aml-primary" disabled={busy} onClick={() => setScreen("challenge")}>{view.challenges?.some((game) => game.status === "active") ? "Resume shift challenge" : "Play shift challenge"}</button></aside>}
        {screen === "alerts" && (selectedAlert ? <AlertDetail key={selectedAlert.id} view={view} alert={selectedAlert} busy={busy} act={act} onBack={() => setAlertId("")} onEntity={openEntity} onCase={openCase} /> : <AlertQueue view={view} busy={busy} act={act} onOpen={openAlert} onCase={openCase} />)}
        {screen === "challenge" && <Challenge key={view.id} view={view} busy={busy} act={act} />}
        {screen === "entities" && <Entities view={view} selectedId={entityId} onSelect={setEntityId} query={query} onQuery={setQuery} onAlert={openAlert} onCase={openCase} />}
        {screen === "cases" && (selectedCase ? <CaseDetail key={`${selectedCase.id}-${view.role}`} view={view} record={selectedCase} busy={busy} act={act} onBack={() => setCaseId("")} onEntity={openEntity} onAlert={openAlert} /> : <CaseQueue view={view} onOpen={openCase} />)}
        {screen === "review" && <Review view={view} busy={busy} act={act} onCase={openCase} />}
        {screen === "comparison" && <RuleComparison key={view.id} view={view} busy={busy} act={act} onResumeChallenge={() => setScreen("challenge")} />}
        {screen === "monitoring" && <Monitoring view={view} busy={busy} act={act} onAlert={openAlert} onCompare={() => setScreen("comparison")} />}
      </>}
    </main>
    <footer className="aml-footer"><span>Synthetic classroom simulation · English interface · Role switching is for training only</span><div><a href="/investigation">The Second Ledger</a><a href="/cases">Case library</a></div></footer>
  </div>;
}

function Badge({ value }: { value: string }) { return <span className={`aml-badge aml-status-${value}`}>{words(value)}</span>; }
function Panel({ title, children, extra }: { title: string; children: ReactNode; extra?: ReactNode }) { return <section className="aml-card"><div className="aml-panel-heading"><h2>{title}</h2>{extra}</div>{children}</section>; }
function Empty({ children }: { children: ReactNode }) { return <p className="aml-empty">{children}</p>; }
function History({ events }: { events: AmlEvent[] }) { return !events.length ? <Empty>No actions recorded for this item.</Empty> : <div className="aml-table-wrap"><table><thead><tr><th scope="col">Time · HKT</th><th scope="col">Actor / role</th><th scope="col">Action</th><th scope="col">Detail</th></tr></thead><tbody>{events.slice().reverse().map((event) => <tr key={event.seq}><td className="aml-nowrap">{time(event.at)}</td><td>{event.actor}<small>{event.role}</small></td><td>{words(event.type)}<small>{event.refId}</small></td><td>{event.detail}</td></tr>)}</tbody></table></div>; }

function AlertQueue({ view, busy, act, onOpen, onCase }: { view: AmlView; busy: boolean; act: Act; onOpen: (id: string) => void; onCase: (id: string) => void }) {
  const [status, setStatus] = useState("active"); const [owner, setOwner] = useState("all"); const [sort, setSort] = useState("priority"); const [latestOnly, setLatestOnly] = useState(false);
  const latest = view.runs.at(-1);
  const alerts = view.alerts.filter((alert) => (status === "all" || status === "active" ? status === "all" || alert.status !== "closed" : alert.status === status) && (owner === "all" || owner === "mine" && alert.owner === view.actor || owner === "unassigned" && !alert.owner) && (!latestOnly || latest?.matchedAlertIds.includes(alert.id))).sort((a, b) => sort === "time" ? b.createdAt.localeCompare(a.createdAt) : sort === "credit" ? b.creditHkd - a.creditHkd : a.priority.localeCompare(b.priority) || b.creditHkd - a.creditHkd);
  return <>
    <div className="aml-page-heading"><div><p className="aml-kicker">Transaction monitoring / triage</p><h1>Alerts</h1><p>Select an alert to inspect its trigger activity, claim ownership and record a disposition.</p></div><div className="aml-metric"><strong>{view.alerts.filter((alert) => alert.status !== "closed").length}</strong><span>active alerts</span></div></div>
    {latest && <div className="aml-context"><strong>Latest monitoring run:</strong> {latest.matchedAlertIds.length} matches · {latest.newAlertIds.length} new alerts · rule v{latest.rule.version} · {time(latest.at)} HKT. Historical alerts remain in the queue when a later rule finds no matches.</div>}
    <Panel title="Alert queue" extra={<span className="aml-help">{alerts.length} shown / {view.alerts.length} total</span>}>
      <div className="aml-filters"><label>Status<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="active">All active</option><option value="all">All statuses</option><option value="new">New</option><option value="claimed">Claimed</option><option value="in_case">In case</option><option value="closed">Closed</option></select></label><label>Assignment<select value={owner} onChange={(event) => setOwner(event.target.value)}><option value="all">All owners</option><option value="mine">My alerts</option><option value="unassigned">Unassigned</option></select></label><label>Sort<select value={sort} onChange={(event) => setSort(event.target.value)}><option value="priority">Priority, then credit amount</option><option value="time">Newest first</option><option value="credit">Largest credits first</option></select></label><label className="aml-check"><input type="checkbox" checked={latestOnly} onChange={(event) => setLatestOnly(event.target.checked)} />Latest run matches only</label></div>
      {!alerts.length ? <Empty>No alerts match these filters. Change the filters or run monitoring as an administrator.</Empty> : <div className="aml-table-wrap"><table><thead><tr><th scope="col">Alert / customer</th><th scope="col">Scenario</th><th scope="col">Priority</th><th scope="col">Window credits</th><th scope="col">Fan-out</th><th scope="col">Status</th><th scope="col">Owner</th><th scope="col">Actions</th></tr></thead><tbody>{alerts.map((alert) => <tr key={alert.id}><td><button className="aml-link" onClick={() => onOpen(alert.id)}>{alert.id}</button><small>{entityName(view, alert.entityId)}</small></td><td>{alert.scenario}<small>{alert.accountId} · rule v{alert.rule.version}</small></td><td><Badge value={alert.priority} /></td><td className="aml-nowrap">{money(alert.creditHkd)}</td><td>{alert.fanOutPercent.toFixed(1)}%</td><td><Badge value={alert.status} /></td><td>{alert.owner || "Unassigned"}</td><td><div className="aml-inline"><button onClick={() => onOpen(alert.id)}>Open</button>{view.role === "analyst" && alert.status === "new" && <button disabled={busy} onClick={() => act({ type: "claim_alert", alertId: alert.id }, `${alert.id} claimed.`)}>Claim</button>}{alert.caseId && <button className="aml-link" onClick={() => onCase(alert.caseId)}>{alert.caseId}</button>}</div></td></tr>)}</tbody></table></div>}
    </Panel>
  </>;
}

function AlertDetail({ view, alert, busy, act, onBack, onEntity, onCase }: { view: AmlView; alert: AmlAlert; busy: boolean; act: Act; onBack: () => void; onEntity: (id: string) => void; onCase: (id: string) => void }) {
  const [tab, setTab] = useState("details"); const [reason, setReason] = useState(""); const [title, setTitle] = useState(`${entityName(view, alert.entityId)} — activity review`); const [existing, setExisting] = useState("");
  const owner = view.role === "analyst" && alert.owner === view.actor && alert.status === "claimed";
  const transactions = view.transactions.filter((transaction) => alert.transactionIds.includes(transaction.id));
  const events = view.events.filter((event) => event.refId === alert.id || event.detail.includes(alert.id) || Boolean(alert.caseId && event.refId === alert.caseId));
  const existingCases = view.cases.filter((record) => record.owner === view.actor && ["investigation", "returned"].includes(record.status));
  async function create(event: FormEvent) { event.preventDefault(); const next = await act({ type: "create_case", alertId: alert.id, title: title.trim() }, "Case created and alert linked."); if (next) { const linked = next.alerts.find((item) => item.id === alert.id)?.caseId; if (linked) onCase(linked); } }
  return <>
    <button className="aml-link aml-back" onClick={onBack}>← Alert queue</button><div className="aml-page-heading"><div><p className="aml-kicker">Alert details / {alert.id}</p><h1>{entityName(view, alert.entityId)}</h1><p>{alert.scenario} · {alert.accountId} · Created {time(alert.createdAt)} HKT</p></div><Badge value={alert.status} /></div>
    <div className="aml-action-bar"><button onClick={() => onEntity(alert.entityId)}>Open customer record</button>{view.role === "analyst" && alert.status === "new" && <button className="aml-primary" disabled={busy} onClick={() => act({ type: "claim_alert", alertId: alert.id }, "Alert claimed. You can now close it or link it to a case.")}>Claim alert</button>}{owner && <button disabled={busy} onClick={() => act({ type: "release_alert", alertId: alert.id }, "Alert released to the unassigned queue.")}>Release ownership</button>}{alert.caseId && <button className="aml-primary" onClick={() => onCase(alert.caseId)}>Open {alert.caseId}</button>}<span className="aml-help">Owner: {alert.owner || "Unassigned"}</span></div>
    <div className="aml-subnav" role="tablist" aria-label="Alert views">{[["details", "Alert Details"], ["activity", "Alert Activity"], ["scoring", "Scoring History"], ["history", "Alert History"]].map(([id, label]) => <button key={id} role="tab" aria-selected={tab === id} onClick={() => setTab(id)}>{label}</button>)}</div>
    {tab === "details" && <div className="aml-two-columns"><div><Panel title="Trigger scorecard"><div className="aml-stat-grid"><div><span>Window credits</span><strong>{money(alert.creditHkd)}</strong><small>Threshold ≥ {money(alert.rule.minCreditHkd)}</small></div><div><span>Outbound / inbound</span><strong>{alert.fanOutPercent.toFixed(1)}%</strong><small>Threshold ≥ {alert.rule.minFanOutPercent}%</small></div><div><span>Window debits</span><strong>{money(alert.debitHkd)}</strong><small>{alert.transactionIds.length} contributing transactions</small></div><div><span>Account age limit</span><strong>{alert.rule.newAccountDays} days</strong><small>Rule snapshot v{alert.rule.version}</small></div></div><p className="aml-help">Window: {time(alert.windowStart)} — {time(alert.windowEnd)} HKT ({alert.rule.windowMinutes} minutes). This is a rule trigger, not a finding of money laundering.</p><button className="aml-link" onClick={() => setTab("activity")}>Inspect contributing transactions →</button></Panel><Panel title="Customer context"><EntityProfile view={view} entity={view.entities.find((entity) => entity.id === alert.entityId)!} /><button className="aml-link" onClick={() => onEntity(alert.entityId)}>Explore accounts, source records and relationships →</button></Panel></div><div><Panel title="Disposition"><p className="aml-help">Claim an unassigned alert as an analyst before changing its disposition. A case is a separate investigation record.</p>{alert.status === "closed" ? <p><strong>Closure reason:</strong> {alert.closureReason}</p> : alert.caseId ? <p>This alert is linked to <button className="aml-link" onClick={() => onCase(alert.caseId)}>{alert.caseId}</button>.</p> : <><form onSubmit={create}><fieldset disabled={busy || !owner}><label>New case title<input value={title} maxLength={200} onChange={(event) => setTitle(event.target.value)} required /></label><button className="aml-primary" disabled={!title.trim()}>Create case from alert</button></fieldset></form><form onSubmit={async (event) => { event.preventDefault(); if (await act({ type: "attach_alert", alertId: alert.id, caseId: existing }, "Alert attached to the existing case.")) onCase(existing); }}><fieldset disabled={busy || !owner}><label>Attach to existing case<select value={existing} onChange={(event) => setExisting(event.target.value)} required><option value="">Select an open case</option>{existingCases.map((record) => <option key={record.id} value={record.id}>{record.id} · {record.title}</option>)}</select></label><button disabled={!existing}>Attach alert</button></fieldset></form><form className="aml-separated" onSubmit={async (event) => { event.preventDefault(); if (await act({ type: "close_alert", alertId: alert.id, reason: reason.trim() }, "Alert closed with rationale preserved.")) setReason(""); }}><fieldset disabled={busy || !owner}><label>Reason for closing without a case<textarea value={reason} rows={3} maxLength={4000} onChange={(event) => setReason(event.target.value)} placeholder="Explain the activity and cite what supports closure." required /></label><button disabled={!reason.trim()}>Close alert</button></fieldset></form></>}</Panel></div></div>}
    {tab === "activity" && <Panel title="Scenario-fired activity"><p>Alert {alert.id} · rule v{alert.rule.version} · monitoring window {time(alert.windowStart)}–{time(alert.windowEnd)} HKT</p><TransactionTable view={view} transactions={transactions} onEntity={onEntity} /></Panel>}
    {tab === "scoring" && <Panel title="Detection rule snapshot"><p>This alert retains the rule version that generated it. Later configuration changes do not rewrite this record.</p><RuleTable rule={alert.rule} /><div className="aml-table-wrap"><table><thead><tr><th>Recorded at · HKT</th><th>Rule version</th><th>Observed credits</th><th>Observed outbound / inbound</th></tr></thead><tbody><tr><td>{time(alert.createdAt)}</td><td>v{alert.rule.version}</td><td>{money(alert.creditHkd)}</td><td>{alert.fanOutPercent.toFixed(1)}%</td></tr></tbody></table></div></Panel>}
    {tab === "history" && <Panel title="Alert history"><History events={events} /></Panel>}
  </>;
}

function EntityProfile({ entity }: { view: AmlView; entity: AmlEntity }) { return <dl className="aml-definition"><div><dt>Customer / identifier</dt><dd>{entity.id} · {entity.identifier}</dd></div><div><dt>Type / jurisdiction / risk</dt><dd>{entity.kind} · {entity.jurisdiction} · <Badge value={entity.risk} /></dd></div><div><dt>Aliases</dt><dd>{entity.aliases.join(" · ") || "None recorded"}</dd></div><div><dt>Declared business</dt><dd>{entity.business}</dd></div><div><dt>Source of funds</dt><dd>{entity.sourceOfFunds}</dd></div><div><dt>Expected monthly activity</dt><dd>{money(entity.expectedMonthlyHkd)}</dd></div><div><dt>Address</dt><dd>{entity.address}</dd></div></dl>; }

function Entities({ view, selectedId, onSelect, query, onQuery, onAlert, onCase }: { view: AmlView; selectedId: string; onSelect: (id: string) => void; query: string; onQuery: (value: string) => void; onAlert: (id: string) => void; onCase: (id: string) => void }) {
  const [tab, setTab] = useState("profile");
  const search = query.trim().toLowerCase();
  const matches = view.entities.filter((entity) => {
    const accounts = view.accounts.filter((account) => account.entityId === entity.id);
    const accountIds = accounts.map((account) => account.id);
    const related = view.transactions.filter((transaction) => accountIds.includes(transaction.fromAccount) || accountIds.includes(transaction.toAccount));
    return [entity.id, entity.name, entity.identifier, entity.business, entity.jurisdiction, ...entity.aliases, ...accountIds, ...related.flatMap((transaction) => [transaction.id, transaction.reference])].some((value) => value.toLowerCase().includes(search));
  });
  const entity = matches.find((item) => item.id === selectedId) || matches[0];
  const accounts = view.accounts.filter((account) => account.entityId === entity?.id);
  const accountIds = accounts.map((account) => account.id);
  const transactions = view.transactions.filter((transaction) => accountIds.includes(transaction.fromAccount) || accountIds.includes(transaction.toAccount));
  const links = view.relationships.filter((relationship) => relationship.fromEntity === entity?.id || relationship.toEntity === entity?.id);
  const evidence = view.evidence.filter((record) => record.entityIds.includes(entity?.id || ""));
  function pivot(id: string) { onQuery(""); onSelect(id); }
  return <><div className="aml-page-heading"><div><p className="aml-kicker">Customer and counterparty intelligence</p><h1>Entities</h1><p>Search source records, inspect account activity and pivot through documented relationships.</p></div></div><div className="aml-entity-layout"><aside className="aml-card aml-entity-list"><label>Find an entity or related record<input type="search" value={query} onChange={(event) => onQuery(event.target.value)} placeholder="Name, ID, account or transaction" /></label><p className="aml-help">{matches.length} entities found</p>{matches.map((item) => <button className={entity?.id === item.id ? "is-active" : ""} key={item.id} onClick={() => onSelect(item.id)}><strong>{item.name}</strong><span>{item.id} · {item.kind} · {item.jurisdiction}</span></button>)}{!matches.length && <Empty>No matching entities.</Empty>}</aside><div className="aml-min-width">{entity && <><div className="aml-record-heading"><div><h2>{entity.name}</h2><span>{entity.id} · {entity.kind}</span></div><Badge value={entity.risk} /></div><div className="aml-subnav" role="tablist" aria-label="Entity views">{[["profile", "Profile & accounts"], ["transactions", `Transactions (${transactions.length})`], ["relationships", `Relationships (${links.length})`], ["evidence", `Source records (${evidence.length})`]].map(([id, label]) => <button key={id} role="tab" aria-selected={tab === id} onClick={() => setTab(id)}>{label}</button>)}</div>{tab === "profile" && <><Panel title="Customer due diligence"><EntityProfile view={view} entity={entity} /></Panel><Panel title="Accounts"><div className="aml-table-wrap"><table><thead><tr><th>Account</th><th>Institution</th><th>Jurisdiction</th><th>Currency</th><th>Opened · HKT</th><th>Visibility</th></tr></thead><tbody>{accounts.map((account) => <tr key={account.id}><td>{account.id}</td><td>{account.bank}</td><td>{account.jurisdiction}</td><td>{account.currency}</td><td>{time(account.openedAt)}</td><td>{account.internal ? "Training bank" : "Known counterparty"}</td></tr>)}</tbody></table></div></Panel><Panel title="Linked work"><div className="aml-inline">{view.alerts.filter((alert) => alert.entityId === entity.id).map((alert) => <button key={alert.id} onClick={() => onAlert(alert.id)}>{alert.id} · {words(alert.status)}</button>)}{view.cases.filter((record) => record.entityIds.includes(entity.id)).map((record) => <button key={record.id} onClick={() => onCase(record.id)}>{record.id} · {words(record.status)}</button>)}</div>{!view.alerts.some((alert) => alert.entityId === entity.id) && !view.cases.some((record) => record.entityIds.includes(entity.id)) && <Empty>No linked alerts or cases.</Empty>}</Panel></>}{tab === "transactions" && <Panel title="Account activity"><TransactionTable view={view} transactions={transactions} onEntity={pivot} /></Panel>}{tab === "relationships" && <Panel title="Relationship exploration"><p className="aml-help">{links.length} direct relationships. Select a connected entity to pivot its profile. A possible link is not a confirmed identity or ownership relationship.</p>{!links.length ? <Empty>No authored relationships for this entity.</Empty> : <div className="aml-table-wrap"><table><thead><tr><th>Connected entity</th><th>Relationship</th><th>Assessment</th><th>Source</th><th>Pivot</th></tr></thead><tbody>{links.map((link) => { const other = link.fromEntity === entity.id ? link.toEntity : link.fromEntity; return <tr key={link.id}><td>{entityName(view, other)}<small>{other}</small></td><td>{link.type}<small>{link.fromEntity} → {link.toEntity}</small></td><td><Badge value={link.confirmed ? "confirmed" : "possible"} /></td><td>{link.source}</td><td><button onClick={() => pivot(other)}>Explore entity</button></td></tr>; })}</tbody></table></div>}</Panel>}{tab === "evidence" && <Panel title="Source records">{evidence.map((record) => <EvidenceRecord key={record.id} record={record} />)}{!evidence.length && <Empty>No source documents are held for this entity.</Empty>}</Panel>}</>}</div></div></>;
}

function EvidenceRecord({ record }: { record: AmlView["evidence"][number] }) { return <details className="aml-evidence"><summary><strong>{record.id}</strong> · {record.title}</summary><p className="aml-help">Source: {record.source}</p><p className="aml-document">{record.body}</p></details>; }

function TransactionTable({ view, transactions, onEntity }: { view: AmlView; transactions: AmlTransaction[]; onEntity: (id: string) => void }) {
  const uid = useId(); const [query, setQuery] = useState(""); const [channel, setChannel] = useState("all"); const [status, setStatus] = useState("all"); const [sort, setSort] = useState("newest");
  const rows = transactions.filter((transaction) => (channel === "all" || channel === transaction.channel) && (status === "all" || status === transaction.status) && `${transaction.id} ${transaction.fromAccount} ${transaction.toAccount} ${transaction.reference} ${transaction.currency} ${transaction.amount}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sort === "amount" ? b.hkdAmount - a.hkdAmount : sort === "oldest" ? a.at.localeCompare(b.at) : b.at.localeCompare(a.at));
  function exportCsv() { const columns: (keyof AmlTransaction)[] = ["id", "at", "fromAccount", "toAccount", "amount", "currency", "hkdAmount", "channel", "reference", "status"]; const cell = (value: string | number) => { const text = String(value); return `"${(/^[\s]*[=+@-]/.test(text) ? `'${text}` : text).replaceAll('"', '""')}"`; }; download([columns.join(","), ...rows.map((row) => columns.map((column) => cell(row[column])).join(","))].join("\r\n"), "twinaml-synthetic-transactions.csv", "text/csv;charset=utf-8"); }
  return <><div className="aml-filters"><label htmlFor={`${uid}-query`}>Search transactions<input id={`${uid}-query`} type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder="ID, account or reference" /></label><label>Channel<select value={channel} onChange={(event) => setChannel(event.target.value)}><option value="all">All channels</option>{["FPS", "CHATS", "SWIFT", "Cash"].map((value) => <option key={value}>{value}</option>)}</select></label><label>Status<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">All statuses</option><option value="executed">Executed</option><option value="pending">Pending</option></select></label><label>Sort<select value={sort} onChange={(event) => setSort(event.target.value)}><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="amount">Largest HKD value</option></select></label></div><div className="aml-table-meta"><span>{rows.length} / {transactions.length} transactions · Original currency and synthetic HKD equivalent</span><button className="aml-link" onClick={exportCsv} disabled={!rows.length}>Export filtered CSV</button></div>{!rows.length ? <Empty>No transactions match these filters.</Empty> : <div className="aml-table-wrap"><table><thead><tr><th>Transaction / time · HKT</th><th>From</th><th>To</th><th>Amount</th><th>HKD equivalent</th><th>Channel / status</th><th>Reference</th></tr></thead><tbody>{rows.map((transaction) => <tr key={transaction.id}><td>{transaction.id}<small className="aml-nowrap">{time(transaction.at)}</small></td><td><button className="aml-link" onClick={() => onEntity(accountEntity(view, transaction.fromAccount))}>{transaction.fromAccount}</button><small>{entityName(view, accountEntity(view, transaction.fromAccount))}</small></td><td><button className="aml-link" onClick={() => onEntity(accountEntity(view, transaction.toAccount))}>{transaction.toAccount}</button><small>{entityName(view, accountEntity(view, transaction.toAccount))}</small></td><td className="aml-nowrap">{money(transaction.amount, transaction.currency)}</td><td className="aml-nowrap">{money(transaction.hkdAmount)}</td><td>{transaction.channel}<small>{transaction.status}</small></td><td>{transaction.reference}</td></tr>)}</tbody></table></div>}</>;
}

function CaseQueue({ view, onOpen }: { view: AmlView; onOpen: (id: string) => void }) {
  const [status, setStatus] = useState("all"); const records = view.cases.filter((record) => status === "all" || record.status === status);
  return <><div className="aml-page-heading"><div><p className="aml-kicker">Investigation management</p><h1>Cases</h1><p>Cases group alerts, entities, cited findings and a reviewable recommendation.</p></div></div><Panel title="Case register"><div className="aml-filters"><label>Status<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">All cases</option>{["investigation", "returned", "pending_review", "closed", "str_approved"].map((value) => <option key={value} value={value}>{words(value)}</option>)}</select></label></div>{!records.length ? <Empty>No cases in this view. Claim an alert, then create a case from Alert Details.</Empty> : <div className="aml-table-wrap"><table><thead><tr><th>Case</th><th>Title</th><th>Status</th><th>Owner</th><th>Alerts / findings</th><th>Recommendation</th><th>Updated · HKT</th></tr></thead><tbody>{records.map((record) => <tr key={record.id}><td><button className="aml-link" onClick={() => onOpen(record.id)}>{record.id}</button></td><td>{record.title}</td><td><Badge value={record.status} /></td><td>{record.owner}</td><td>{record.alertIds.length} / {record.findings.length}</td><td>{record.recommendation === "str" ? "STR training draft" : "Close case"}</td><td>{time(record.updatedAt)}</td></tr>)}</tbody></table></div>}</Panel></>;
}

function exportCase(view: AmlView, record: AmlCase) {
  download(JSON.stringify({ label: "TRAINING DRAFT — SYNTHETIC DATA — NOT SUBMITTED TO JFIU", runId: view.id, exportedAt: new Date().toISOString(), case: record, entities: view.entities.filter((entity) => record.entityIds.includes(entity.id)), alerts: view.alerts.filter((alert) => record.alertIds.includes(alert.id)), transactions: view.transactions.filter((transaction) => record.transactionIds.includes(transaction.id)), evidence: view.evidence.filter((evidence) => record.findings.some((finding) => finding.evidenceIds.includes(evidence.id))), history: view.events.filter((event) => event.refId === record.id || event.detail.includes(record.id)) }, null, 2), `twinaml-${record.id}-TRAINING-DRAFT.json`);
}

function CaseDetail({ view, record, busy, act, onBack, onEntity, onAlert }: { view: AmlView; record: AmlCase; busy: boolean; act: Act; onBack: () => void; onEntity: (id: string) => void; onAlert: (id: string) => void }) {
  const [tab, setTab] = useState("investigation"); const [narrative, setNarrative] = useState(record.narrative); const [recommendation, setRecommendation] = useState(record.recommendation); const [strDraft, setStrDraft] = useState<StrDraft>({ ...record.strDraft });
  const [finding, setFinding] = useState(""); const [txIds, setTxIds] = useState<string[]>([]); const [evIds, setEvIds] = useState<string[]>([]);
  const editable = view.role === "analyst" && record.owner === view.actor && ["investigation", "returned"].includes(record.status);
  const dirty = narrative !== record.narrative || recommendation !== record.recommendation || JSON.stringify(strDraft) !== JSON.stringify(record.strDraft);
  const relatedIds = new Set(record.entityIds); view.relationships.forEach((link) => { if (record.entityIds.includes(link.fromEntity) || record.entityIds.includes(link.toEntity)) { relatedIds.add(link.fromEntity); relatedIds.add(link.toEntity); } });
  const evidence = view.evidence.filter((item) => item.entityIds.some((id) => relatedIds.has(id)));
  const transactions = view.transactions.filter((transaction) => record.transactionIds.includes(transaction.id) || relatedIds.has(accountEntity(view, transaction.fromAccount)) || relatedIds.has(accountEntity(view, transaction.toAccount)));
  const complete = narrative.trim().length >= 20 && record.findings.length && (recommendation === "close" || Object.values(strDraft).every((value) => value.trim()));
  const events = view.events.filter((event) => event.refId === record.id || event.detail.includes(record.id));
  function toggle(list: string[], id: string) { return list.includes(id) ? list.filter((value) => value !== id) : [...list, id]; }
  async function saveDraft(message: string) {
    const next = await act({ type: "save_case", caseId: record.id, narrative, recommendation, strDraft }, message);
    const saved = next?.cases.find((item) => item.id === record.id);
    if (saved) { setNarrative(saved.narrative); setRecommendation(saved.recommendation); setStrDraft({ ...saved.strDraft }); }
  }
  return <><button className="aml-link aml-back" onClick={onBack}>← Case register</button><div className="aml-page-heading"><div><p className="aml-kicker">Case file / {record.id}</p><h1>{record.title}</h1><p>Owner {record.owner} · Updated {time(record.updatedAt)} HKT</p></div><Badge value={record.status} /></div><div className="aml-action-bar"><button onClick={() => exportCase(view, record)}>Export saved case dossier</button><span className="aml-help">TRAINING DRAFT · No report is sent to JFIU.</span></div>{record.status === "returned" && record.reviews.at(-1) && <div className="aml-context"><strong>Returned for further work:</strong> {record.reviews.at(-1)?.reason}</div>}{!editable && <div className="aml-context">Read-only case. Analyst editing is available for an owned case in investigation or returned status.</div>}
    <div className="aml-subnav" role="tablist" aria-label="Case views">{[["investigation", "Investigation"], ["str", "STR training draft"], ["transactions", "Linked transactions"], ["history", "Case history"]].map(([id, label]) => <button key={id} role="tab" aria-selected={tab === id} onClick={() => setTab(id)}>{label}</button>)}</div>
    {tab === "investigation" && <div className="aml-two-columns"><div><Panel title="Investigation narrative"><form onSubmit={async (event) => { event.preventDefault(); await saveDraft("Case draft saved."); }}><fieldset disabled={busy || !editable}><label>Activity, analysis and remaining gaps<textarea value={narrative} onChange={(event) => setNarrative(event.target.value)} rows={7} maxLength={12000} placeholder="Explain expected vs observed activity, evidence, legitimate explanations and what remains unknown." required /></label><label>Recommendation<select value={recommendation} onChange={(event) => setRecommendation(event.target.value as "close" | "str")}><option value="close">Close case with rationale</option><option value="str">Escalate with STR training draft</option></select></label><div className="aml-inline"><button className="aml-primary" disabled={!dirty}>Save draft</button>{dirty && <span className="aml-help">Unsaved changes</span>}</div></fieldset></form><div className="aml-separated"><button className="aml-primary" disabled={busy || !editable || dirty || !complete} onClick={() => act({ type: "submit_case", caseId: record.id }, "Case submitted. Switch to the reviewer training role to review it.")}>Submit for review</button><p className="aml-help">Save a narrative of at least 20 characters and at least one cited finding before submitting. An STR recommendation also requires all five training-draft fields. {dirty && "Save your current edits first."}</p>{recommendation === "str" && <button className="aml-link" onClick={() => setTab("str")}>Complete the STR training draft →</button>}</div></Panel><Panel title={`Cited findings (${record.findings.length})`}><Findings view={view} record={record} />{editable && <form className="aml-separated" onSubmit={async (event) => { event.preventDefault(); const next = await act({ type: "add_finding", caseId: record.id, text: finding.trim(), transactionIds: txIds, evidenceIds: evIds }, "Finding and source citations added."); if (next) { setFinding(""); setTxIds([]); setEvIds([]); } }}><fieldset disabled={busy}><label>New finding<textarea value={finding} onChange={(event) => setFinding(event.target.value)} rows={4} maxLength={6000} placeholder="State an observation and why it matters. Cite supporting records below." required /></label><details className="aml-citation-picker"><summary>Transaction citations ({txIds.length} selected)</summary><div>{transactions.map((transaction) => <label className="aml-check" key={transaction.id}><input type="checkbox" checked={txIds.includes(transaction.id)} onChange={() => setTxIds(toggle(txIds, transaction.id))} /><span>{transaction.id} · {money(transaction.amount, transaction.currency)} · {transaction.fromAccount} → {transaction.toAccount}</span></label>)}</div></details><details className="aml-citation-picker"><summary>Evidence citations ({evIds.length} selected)</summary><div>{evidence.map((item) => <label className="aml-check" key={item.id}><input type="checkbox" checked={evIds.includes(item.id)} onChange={() => setEvIds(toggle(evIds, item.id))} /><span>{item.id} · {item.title}</span></label>)}</div></details><button disabled={!finding.trim() || !txIds.length && !evIds.length}>Add cited finding</button></fieldset></form>}</Panel></div><div><Panel title="Linked work"><h3>Alerts</h3><div className="aml-inline">{record.alertIds.map((id) => <button key={id} onClick={() => onAlert(id)}>{id}</button>)}</div><h3 className="aml-spaced">Entities</h3><div className="aml-inline">{record.entityIds.map((id) => <button key={id} onClick={() => onEntity(id)}>{entityName(view, id)}</button>)}</div></Panel><Panel title="Available source records">{evidence.map((item) => <EvidenceRecord key={item.id} record={item} />)}</Panel></div></div>}
    {tab === "str" && <Panel title="Suspicious transaction report · TRAINING DRAFT"><p className="aml-context">Structured practice narrative for internal review. This is not the official STREAMS 2 form and cannot file a report.</p><form onSubmit={async (event) => { event.preventDefault(); await saveDraft("STR training draft and case changes saved."); }}><fieldset disabled={busy || !editable}>{([["subjects", "Subjects and relationships", "Who is involved? Identify customers, counterparties, accounts and known relationships."], ["period", "Activity period", "State the relevant dates and times, including the time zone."], ["activity", "Transactions and activity", "Describe amounts, currencies, channels and transaction sequence; cite IDs."], ["suspicion", "Grounds for suspicion", "Explain the specific facts and patterns supporting suspicion without asserting an unproven crime."], ["explanation", "Customer explanation and unresolved gaps", "Record alternative explanations, checks completed and information still missing."]] as [keyof StrDraft, string, string][]).map(([key, label, placeholder]) => <label key={key}>{label}<textarea value={strDraft[key]} rows={3} maxLength={key === "subjects" ? 4000 : key === "period" ? 1000 : 6000} placeholder={placeholder} onChange={(event) => setStrDraft({ ...strDraft, [key]: event.target.value })} /></label>)}<button className="aml-primary" disabled={!dirty}>Save training draft</button></fieldset></form></Panel>}
    {tab === "transactions" && <Panel title="Linked transaction records"><TransactionTable view={view} transactions={view.transactions.filter((transaction) => record.transactionIds.includes(transaction.id))} onEntity={onEntity} /></Panel>}
    {tab === "history" && <><Panel title="Review decisions">{record.reviews.length ? record.reviews.slice().reverse().map((review, index) => <div className="aml-finding" key={index}><strong>{words(review.decision)}</strong><small>{review.author} · {time(review.at)} HKT</small><p>{review.reason}</p></div>) : <Empty>No reviewer decisions yet.</Empty>}</Panel><Panel title="Case action history"><History events={events} /></Panel></>}
  </>;
}

function Findings({ view, record }: { view: AmlView; record: AmlCase }) { return !record.findings.length ? <Empty>No findings yet. Record an observation and cite a transaction or evidence record.</Empty> : <>{record.findings.map((finding) => <article className="aml-finding" key={finding.id}><strong>{finding.id}</strong><small>{finding.author} · {time(finding.at)} HKT</small><p className="aml-document">{finding.text}</p><div className="aml-citations">{finding.transactionIds.map((id) => <span key={id}>{id}</span>)}{finding.evidenceIds.map((id) => <span key={id} title={view.evidence.find((item) => item.id === id)?.title}>{id}</span>)}</div></article>)}</>; }

function Review({ view, busy, act, onCase }: { view: AmlView; busy: boolean; act: Act; onCase: (id: string) => void }) {
  const [selected, setSelected] = useState(""); const [reason, setReason] = useState("");
  const pending = view.cases.filter((record) => record.status === "pending_review"); const record = pending.find((item) => item.id === selected) || pending[0];
  async function decide(decision: "return" | "approve_close" | "approve_str") { if (!record) return; if (await act({ type: "review_case", caseId: record.id, decision, reason: reason.trim() }, decision === "return" ? "Case returned to the analyst with review feedback." : "Reviewer decision recorded. This is a training outcome; no report was filed.")) setReason(""); }
  return <><div className="aml-page-heading"><div><p className="aml-kicker">Independent case review</p><h1>Review queue</h1><p>Check evidence, reasoning and the proposed outcome before accepting or returning a case.</p></div><div className="aml-metric"><strong>{pending.length}</strong><span>pending review</span></div></div>{view.role !== "reviewer" && <div className="aml-context">Switch the training role to Reviewer to record a review decision.</div>}<Panel title="Cases awaiting review">{!pending.length ? <Empty>No cases await review. An analyst must save a complete investigation and submit it first.</Empty> : <><div className="aml-table-wrap"><table><thead><tr><th>Case</th><th>Title</th><th>Analyst</th><th>Recommendation</th><th>Submitted / updated · HKT</th></tr></thead><tbody>{pending.map((item) => <tr key={item.id} className={record?.id === item.id ? "aml-selected-row" : ""}><td><button className="aml-link" onClick={() => { setSelected(item.id); setReason(""); }}>{item.id}</button></td><td>{item.title}</td><td>{item.owner}</td><td>{item.recommendation === "str" ? "STR training draft" : "Case closure"}</td><td>{time(item.updatedAt)}</td></tr>)}</tbody></table></div></>}</Panel>{record && <div className="aml-two-columns"><div><Panel title={`${record.id} / analyst submission`} extra={<button onClick={() => onCase(record.id)}>Open full case</button>}><h3>Investigation narrative</h3><p className="aml-document">{record.narrative}</p><h3>Cited findings</h3><Findings view={view} record={record} />{record.recommendation === "str" && <><h3 className="aml-spaced">STR training draft</h3><dl className="aml-definition">{Object.entries(record.strDraft).map(([key, value]) => <div key={key}><dt>{words(key)}</dt><dd className="aml-document">{value}</dd></div>)}</dl></>}<button onClick={() => exportCase(view, record)}>Export saved case dossier</button></Panel></div><Panel title="Reviewer action"><form onSubmit={(event) => { event.preventDefault(); decide(record.recommendation === "str" ? "approve_str" : "approve_close"); }}><fieldset disabled={busy || view.role !== "reviewer"}><label>Review rationale<textarea value={reason} onChange={(event) => setReason(event.target.value)} rows={6} maxLength={4000} required placeholder="Explain your assessment of the evidence and decision. For a return, identify the additional work required." /></label><div className="aml-stack"><button className="aml-primary" disabled={!reason.trim()}>{record.recommendation === "str" ? "Approve STR training draft" : "Approve case closure"}</button><button type="button" disabled={!reason.trim()} onClick={() => decide("return")}>Return for further work</button></div><p className="aml-help">Approvals follow the analyst's recommendation. Returning the case allows the analyst to amend it and submit again.</p></fieldset></form></Panel></div>}</>;
}

function RuleTable({ rule }: { rule: MonitoringRule }) { return <dl className="aml-definition"><div><dt>Rule version</dt><dd>v{rule.version}</dd></div><div><dt>Minimum window credits</dt><dd>{money(rule.minCreditHkd)}</dd></div><div><dt>Minimum outbound / inbound</dt><dd>{rule.minFanOutPercent}%</dd></div><div><dt>Monitoring window</dt><dd>{rule.windowMinutes} minutes</dd></div><div><dt>Maximum account age</dt><dd>{rule.newAccountDays} days</dd></div></dl>; }

function Monitoring({ view, busy, act, onAlert, onCompare }: { view: AmlView; busy: boolean; act: Act; onAlert: (id: string) => void; onCompare: () => void }) {
  const [rule, setRule] = useState<Omit<MonitoringRule, "version">>({ minCreditHkd: view.rule.minCreditHkd, minFanOutPercent: view.rule.minFanOutPercent, windowMinutes: view.rule.windowMinutes, newAccountDays: view.rule.newAccountDays });
  useEffect(() => { setRule({ minCreditHkd: view.rule.minCreditHkd, minFanOutPercent: view.rule.minFanOutPercent, windowMinutes: view.rule.windowMinutes, newAccountDays: view.rule.newAccountDays }); }, [view.rule.version, view.rule.minCreditHkd, view.rule.minFanOutPercent, view.rule.windowMinutes, view.rule.newAccountDays]);
  const administrator = view.role === "administrator"; const latest = view.runs.at(-1);
  const dirty = rule.minCreditHkd !== view.rule.minCreditHkd || rule.minFanOutPercent !== view.rule.minFanOutPercent || rule.windowMinutes !== view.rule.windowMinutes || rule.newAccountDays !== view.rule.newAccountDays;
  return <><div className="aml-page-heading"><div><p className="aml-kicker">Scenario administration</p><h1>Monitoring</h1><p>Change a versioned rule, run detection and inspect which transactions produced each alert.</p></div><button onClick={onCompare}>Compare rules on five benchmark scenarios</button></div>{!administrator && <div className="aml-context">Read-only configuration. Switch the training role to Administrator to change the rule, add records or run monitoring.</div>}<div className="aml-two-columns"><Panel title={`Rapid movement on a new account / rule v${view.rule.version}`}><form onSubmit={async (event) => { event.preventDefault(); await act({ type: "configure_rule", rule }, "New rule version saved. Run monitoring to apply it to the synthetic data."); }}><fieldset disabled={busy || !administrator}>{([["minCreditHkd", "Minimum credits in window · HKD", 1, 1000000000, "1"], ["minFanOutPercent", "Minimum outbound / inbound · %", 1, 100, "1"], ["windowMinutes", "Window length · minutes", 1, 1440, "1"], ["newAccountDays", "Maximum account age · days", 1, 365, "1"]] as [keyof Omit<MonitoringRule, "version">, string, number, number | undefined, string][]).map(([key, label, min, max, step]) => <label key={key}>{label}<input type="number" value={rule[key]} min={min} max={max} step={step} onChange={(event) => setRule({ ...rule, [key]: Number(event.target.value) })} required /></label>)}<div className="aml-inline"><button className="aml-primary" disabled={!dirty}>Save rule version</button><button type="button" disabled={dirty} onClick={() => act({ type: "run_monitoring" }, "Monitoring run completed. Review matches and newly generated alerts below.")}>Run monitoring</button></div></fieldset></form><p className="aml-help">Save rule edits before running. Rules generate alerts for investigation; they do not decide whether a customer has laundered money. Historical alerts retain their original rule snapshot.</p></Panel><Panel title="Latest detection result">{latest ? <><div className="aml-stat-grid"><div><span>Matched alerts</span><strong>{latest.matchedAlertIds.length}</strong></div><div><span>New alerts</span><strong>{latest.newAlertIds.length}</strong></div><div><span>Transactions inspected</span><strong>{latest.transactionCount}</strong></div><div><span>Rule version</span><strong>v{latest.rule.version}</strong></div></div><p>{latest.id} · {time(latest.at)} HKT</p><div className="aml-inline">{latest.matchedAlertIds.map((id) => <button key={id} onClick={() => onAlert(id)}>{id}</button>)}</div>{!latest.matchedAlertIds.length && <Empty>No activity met this rule in the current dataset. Existing alerts remain in their prior workflow state.</Empty>}</> : <Empty>No monitoring runs yet.</Empty>}</Panel></div><Panel title="Add a synthetic transaction"><p className="aml-help">Add a source record, then run monitoring. Detection uses executed transactions in the last seven days. Times are entered in HKT and stored as UTC. Whole-unit amounts use fixed exercise rates: USD 1 = HKD 7.80; RMB 1 = HKD 1.08.</p><AddTransaction view={view} busy={busy} act={act} disabled={!administrator} /></Panel><Panel title="Monitoring run history"><div className="aml-table-wrap"><table><thead><tr><th>Run / time · HKT</th><th>Rule</th><th>Input transactions</th><th>Matches / new</th><th>Matched alerts</th></tr></thead><tbody>{view.runs.slice().reverse().map((run) => <tr key={run.id}><td>{run.id}<small>{time(run.at)}</small></td><td><details><summary>v{run.rule.version}</summary><RuleTable rule={run.rule} /></details></td><td>{run.transactionCount}</td><td>{run.matchedAlertIds.length} / {run.newAlertIds.length}</td><td><div className="aml-inline">{run.matchedAlertIds.map((id) => <button className="aml-link" key={id} onClick={() => onAlert(id)}>{id}</button>)}</div></td></tr>)}</tbody></table></div></Panel><Panel title="Run audit history"><History events={view.events} /></Panel></>;
}

function AddTransaction({ view, busy, act, disabled }: { view: AmlView; busy: boolean; act: Act; disabled: boolean }) {
  const [id, setId] = useState(""); const [at, setAt] = useState(localInput(view.asOf)); const [from, setFrom] = useState(view.accounts[0]?.id || ""); const [to, setTo] = useState(view.accounts[1]?.id || ""); const [amount, setAmount] = useState(100000); const [currency, setCurrency] = useState<AmlTransaction["currency"]>("HKD"); const [channel, setChannel] = useState<AmlTransaction["channel"]>("FPS"); const [status, setStatus] = useState<AmlTransaction["status"]>("executed"); const [reference, setReference] = useState("");
  const hkdAmount = Math.round(amount * (currency === "USD" ? 780 : currency === "RMB" ? 108 : 100) / 100);
  const earliest = Math.max(new Date(view.asOf).getTime() - 365 * 86400000, ...view.accounts.filter((account) => account.id === from || account.id === to).map((account) => new Date(account.openedAt).getTime()));
  const validAccounts = from !== to && view.accounts.some((account) => (account.id === from || account.id === to) && account.internal);
  async function submit(event: FormEvent) { event.preventDefault(); const transaction: AmlTransaction = { id: id.trim() || `TX-MANUAL-${Date.now().toString(36).toUpperCase()}`, at: new Date(`${at}:00+08:00`).toISOString(), fromAccount: from, toAccount: to, amount, currency, hkdAmount, channel, reference: reference.trim(), status }; if (await act({ type: "add_transaction", transaction }, `${transaction.id} added. Run monitoring to test its effect.`)) { setId(""); setReference(""); } }
  const options = view.accounts.map((account) => <option key={account.id} value={account.id}>{account.id} · {entityName(view, account.entityId)}</option>);
  return <form onSubmit={submit}><fieldset disabled={busy || disabled}><div className="aml-form-grid"><label>Transaction ID · optional<input value={id} maxLength={64} pattern="[A-Za-z0-9][A-Za-z0-9_-]*" onChange={(event) => setId(event.target.value)} placeholder="Generated if blank" /></label><label>Time · HKT<input type="datetime-local" value={at} min={localInput(new Date(earliest).toISOString())} max={localInput(view.asOf)} onChange={(event) => setAt(event.target.value)} required /></label><label>From account<select value={from} onChange={(event) => setFrom(event.target.value)} required>{options}</select></label><label>To account<select value={to} onChange={(event) => setTo(event.target.value)} required>{options}</select></label><label>Currency<select value={currency} onChange={(event) => setCurrency(event.target.value as AmlTransaction["currency"])}><option>HKD</option><option disabled={channel === "FPS"}>USD</option><option>RMB</option></select></label><label>Amount<input type="number" value={amount} min="1" max="1000000000" step="1" onChange={(event) => setAmount(Number(event.target.value))} required /></label><label>HKD equivalent<input type="number" value={hkdAmount} readOnly /></label><label>Channel<select value={channel} onChange={(event) => { setChannel(event.target.value as AmlTransaction["channel"]); if (event.target.value === "FPS") { setStatus("executed"); if (currency === "USD") setCurrency("HKD"); } }}><option>FPS</option><option>CHATS</option><option>SWIFT</option><option>Cash</option></select></label><label>Status<select value={status} onChange={(event) => setStatus(event.target.value as AmlTransaction["status"])}><option value="executed">Executed</option><option value="pending" disabled={channel === "FPS"}>Pending</option></select></label><label>Payment reference<input value={reference} maxLength={500} onChange={(event) => setReference(event.target.value)} required /></label></div><button disabled={!validAccounts || !reference.trim()} className="aml-primary">Add synthetic transaction</button>{!validAccounts && <p className="aml-help">Choose different accounts, including at least one account at the training bank.</p>}</fieldset></form>;
}
